23|function toResponse(res: ImageResponse): { json: ImageResponse; status: number } {
24|  if (res.status === "ready" || res.status === "pending") return { json: res, status: 200 };
25|  const status = res.code === "bad_request" ? 400 : res.code === "quota" ? 429 : 503;
26|  return { json: res, status };
