1|// Picture state for one scene: the pane card plus inline figures.
2|// The client sends ordinals and ids only, never text. Session caches
3|// survive sub-page and scene moves, so a shown picture never refetches.
4|//
5|// Ordering rules: one request at a time across scene and figure. The
6|// module-level `inFlight` record names what is generating, so a scene
7|// switch shows `loading` only for that; a second request while one is in
8|// flight shows a short hint where it was asked. retryFigure only works
9|// from the error phase; the caller must call hidePopover on pager moves. The style pref arrives as a hook argument and is read through a
10|// ref, so the callbacks stay stable when it changes.
11|"use client";
12|
13|import { useCallback, useEffect, useMemo, useRef, useState } from "react";
14|import { MSG_FAILED, MSG_RETRY } from "@/core/images";
15|import { canIllustrateScene, canRetryFigure } from "./figure-placement";
16|import { PICTURE_COPY } from "./picture-copy";
17|import type { ImageResponse } from "@/core/images";
18|import { requestStyleFields, styleCredit } from "../image-style";
19|import type { ImageStylePref } from "../image-style";
20|import { pickEndN, pickStartN } from "../picture-selection";
21|import type { ParaEntry } from "../picture-selection";
22|
23|export type SceneCard =
24|  | { phase: "idle"; hint?: string }
25|  | { phase: "loading" }
26|  | { phase: "ready"; url: string; caption: string }
27|  | { phase: "error"; message: string };
28|
29|export interface InlineFigure {
30|  id: string;
31|  phase: "loading" | "ready" | "error";
32|  url: string | null;
33|  quote: string;
34|  startN: number;
35|  endN: number;
36|  credit: string;
37|  message: string | null;
38|}
39|
40|export interface LightboxItem {
41|  src: string;
42|  caption: string;
43|}
44|
45|const POLL_MS = 3000;
46|const POLL_MAX = 40;
47|const HINT_MS = 2400;
48|
49|// What is generating right now, across scene moves. One at a time.
50|export type InFlight = { kind: "scene"; sceneId: string } | { kind: "figure"; sceneId: string; id: string } | null;
51|let inFlight: InFlight = null;
52|
53|function release(mine: InFlight): void {
54|  if (inFlight === mine) inFlight = null;
55|}
56|
57|function sceneCard(sceneId: string): SceneCard {
58|  const hit = sceneCache.get(sceneId);
59|  if (hit) return { phase: "ready", url: hit.url, caption: hit.caption };
60|  return inFlight?.kind === "scene" && inFlight.sceneId === sceneId ? { phase: "loading" } : { phase: "idle" };
61|}
62|
63|// Cached figures for a scene; a loading one shows only while it really is
64|// the request in flight.
65|function sceneFigures(sceneId: string): InlineFigure[] {
66|  return (figureCache.get(sceneId) ?? []).filter(
67|    (f) => f.phase !== "loading" || (inFlight?.kind === "figure" && inFlight.sceneId === sceneId && inFlight.id === f.id),
68|  );
69|}
70|
71|type HintAt = { where: "scene" } | { where: "popover" } | { where: "figure"; id: string } | null;
72|
73|const sceneCache = new Map<string, { url: string; caption: string }>();
74|
75|// Read-only view of the session cache for the panels grid. Never
76|// writes, so it cannot change picture behaviour.
77|export function getCachedScenePicture(sceneId: string): { url: string; caption: string } | null {
78|  const hit = sceneCache.get(sceneId);
79|  return hit ? { url: hit.url, caption: hit.caption } : null;
80|}
81|const figureCache = new Map<string, InlineFigure[]>();
82|let figureSeq = 1;
83|
84|// Document coordinates from the selection rect plus page scroll, so the
85|// popover stays on the selection however scenes are laid out (paged or
86|// continuous scroll, several scenes mounted at once).
87|export function popoverPos(
88|  rect: { top: number; left: number; width: number },
89|  scroll: { x: number; y: number },
90|): { top: number; left: number } {
91|  return { top: rect.top + scroll.y - 8, left: rect.left + scroll.x + rect.width / 2 };
92|}
93|
94|function paraOf(node: Node | null): Element | null {
95|  if (!node) return null;
96|  const el = node.nodeType === Node.TEXT_NODE ? node.parentElement : (node as Element);
97|  return el?.closest?.("p[id]") ?? null;
