126|export function usePictures({
127|  bookId,
128|  textVersion,
129|  sceneId,
130|  pref,
131|}: {
132|  bookId: string;
133|  textVersion: string;
134|  sceneId: string;
135|  pref: ImageStylePref;
136|}) {
137|  const [card, setCard] = useState<SceneCard>(() => sceneCard(sceneId));
138|  const [figures, setFigures] = useState<InlineFigure[]>(() => sceneFigures(sceneId));
139|  const [hintAt, setHintAt] = useState<HintAt>(null);
140|  const hintTimer = useRef<number | null>(null);
141|  const [popover, setPopover] = useState<{ top: number; left: number } | null>(null);
142|  const [lightbox, setLightbox] = useState<LightboxItem | null>(null);
143|  // The text view mounts late on a chapter's first scene (cover first),
144|  // so the node is tracked in state and the listener follows it.
145|  const viewNodeRef = useRef<HTMLDivElement | null>(null);
146|  const [viewEl, setViewEl] = useState<HTMLDivElement | null>(null);
147|  const viewRef = useCallback((node: HTMLDivElement | null) => {
148|    viewNodeRef.current = node;
149|    setViewEl(node);
150|  }, []);
151|  const popRef = useRef<HTMLButtonElement | null>(null);
152|  // The selected range, kept so the portalled popover can follow it when
153|  // any scroll container (window or the reading column) moves the text.
154|  const rangeRef = useRef<Range | null>(null);
155|  const openerRef = useRef<HTMLElement | null>(null);
156|  const prefRef = useRef(pref);
157|  prefRef.current = pref;
158|  // The continuous reader reuses one hook call while the scene in view
159|  // changes: track it so late poll results cannot paint another scene.
160|  const sceneRef = useRef(sceneId);
161|  sceneRef.current = sceneId;
162|
163|  const hidePopover = useCallback(() => setPopover(null), []);
164|
165|  // The card and figures follow the scene in view through the session
166|  // caches; in-flight requests keep filling the cache they started.
167|  useEffect(() => {
168|    setCard(sceneCard(sceneId));
169|    setFigures(sceneFigures(sceneId));
170|    setPopover(null);
171|    setHintAt(null);
172|  }, [sceneId]);
173|
174|  useEffect(
175|    () => () => {
176|      if (hintTimer.current !== null) window.clearTimeout(hintTimer.current);
177|    },
178|    [],
179|  );
180|
181|  // Another picture is generating: say so where the reader asked.
182|  const showHint = useCallback((at: NonNullable<HintAt>) => {
183|    setHintAt(at);
184|    if (hintTimer.current !== null) window.clearTimeout(hintTimer.current);
185|    hintTimer.current = window.setTimeout(() => {
186|      hintTimer.current = null;
187|      setHintAt(null);
188|    }, HINT_MS);
189|  }, []);
190|
191|  // Writes the scene's own cache entry; paints only if it is still current.
192|  const storeFigures = useCallback((scene: string, update: (prev: InlineFigure[]) => InlineFigure[]) => {
193|    const value = update(figureCache.get(scene) ?? []);
194|    figureCache.set(scene, value);
195|    if (sceneRef.current === scene) setFigures(value);
196|  }, []);
197|
198|  const openLightbox = useCallback((src: string, caption: string, opener: HTMLElement | null) => {
199|    openerRef.current = opener;
200|    setLightbox({ src, caption });
201|  }, []);
202|
203|  const closeLightbox = useCallback(() => {
204|    setLightbox(null);
205|    openerRef.current?.focus?.();
206|    openerRef.current = null;
207|  }, []);
208|
209|  const illustrateScene = useCallback(() => {
210|    if (inFlight !== null && sceneId !== "" && !sceneCache.has(sceneId)) {
211|      showHint({ where: "scene" });
212|      return;
213|    }
214|    if (!canIllustrateScene({ sceneId, busy: inFlight !== null, cached: sceneCache.has(sceneId) })) return;
215|    const mine: InFlight = { kind: "scene", sceneId };
216|    inFlight = mine;
217|    setPopover(null);
218|    setHintAt(null);
219|    setCard({ phase: "loading" });
220|    void poll({ kind: "scene", bookId, textVersion, sceneId, ...requestStyleFields(prefRef.current) })
221|      .then(({ url, caption }) => {
222|        sceneCache.set(sceneId, { url, caption });
223|        if (sceneRef.current === sceneId) setCard({ phase: "ready", url, caption });
224|      })
225|      .catch((err: unknown) => {
226|        if (sceneRef.current === sceneId) {
227|          setCard({ phase: "error", message: err instanceof Error ? err.message : MSG_FAILED });
228|        }
229|      })
230|      .finally(() => {
231|        release(mine);
232|      });
233|  }, [bookId, textVersion, sceneId, showHint]);
234|
235|  const clearScene = useCallback(() => {
236|    sceneCache.delete(sceneId);
237|    setCard({ phase: "idle" });
238|  }, [sceneId]);
239|
240|  const requestFigure = useCallback(
241|    (scene: string, id: string, startN: number) => {
242|      // Callers claim inFlight; this starts the request and releases it.
243|      const mine = inFlight;
244|      void poll({ kind: "passage", bookId, textVersion, n: startN, ...requestStyleFields(prefRef.current) })
245|        .then(({ url }) => {
246|          storeFigures(scene, (prev) =>
247|            prev.map((f) => (f.id === id ? { ...f, phase: "ready", url, message: null } : f)),
248|          );
249|        })
250|        .catch((err: unknown) => {
251|          storeFigures(scene, (prev) =>
252|            prev.map((f) =>
253|              f.id === id
254|                ? { ...f, phase: "error", message: err instanceof Error ? err.message : MSG_FAILED }
255|                : f,
256|            ),
257|          );
258|        })
259|        .finally(() => {
260|          release(mine);
261|        });
262|    },
263|    [bookId, textVersion, storeFigures],
264|  );
265|
266|  const illustratePassage = useCallback(() => {
267|    const view = viewNodeRef.current;
268|    const sel = window.getSelection();
269|    if (!view || !sel || !sel.rangeCount) return;
270|    if (inFlight !== null) {
271|      showHint({ where: "popover" });
272|      return;
273|    }
274|    const quote = sel.toString().trim();
275|    if (quote.length < 3) return;
276|    const entries: ParaEntry[] = [...view.querySelectorAll("p[id][data-n]")].map((el) => ({
277|      id: el.id,
278|      n: Number(el.getAttribute("data-n")),
279|    }));
280|    const startN = pickStartN(entries, paraOf(sel.anchorNode)?.id ?? null, paraOf(sel.focusNode)?.id ?? null);
281|    const endN = pickEndN(entries, paraOf(sel.anchorNode)?.id ?? null, paraOf(sel.focusNode)?.id ?? null);
282|    if (startN === null || endN === null) return;
283|    setPopover(null);
284|    sel.removeAllRanges();
285|    const id = `f${figureSeq++}`;
286|    const scene = sceneRef.current;
287|    inFlight = { kind: "figure", sceneId: scene, id };
288|    const credit = styleCredit(requestStyleFields(prefRef.current));
289|    storeFigures(scene, (prev) => [
290|      ...prev,
291|      { id, phase: "loading", url: null, quote, startN, endN, credit, message: null },
292|    ]);
293|    requestFigure(scene, id, startN);
294|  }, [requestFigure, storeFigures, showHint]);
295|
296|  const retryFigure = useCallback(
297|    (id: string) => {
298|      const found = figureCache.get(sceneId)?.find((f) => f.id === id);
299|      if (found?.phase === "error" && inFlight !== null) {
300|        showHint({ where: "figure", id });
301|        return;
302|      }
303|      if (!canRetryFigure(found, inFlight !== null)) return;
304|      inFlight = { kind: "figure", sceneId, id };
305|      setHintAt(null);
306|      storeFigures(sceneId, (prev) => prev.map((f) => (f.id === id ? { ...f, phase: "loading", message: null } : f)));
307|      requestFigure(sceneId, id, found.startN);
308|    },
309|    [requestFigure, storeFigures, sceneId, showHint],
310|  );
311|
312|  const removeFigure = useCallback(
313|    (id: string) => {
314|      storeFigures(sceneId, (prev) => prev.filter((f) => f.id !== id));
315|    },
316|    [storeFigures, sceneId],
317|  );
318|
319|  // Re-read the live selection against the current text view. The
320|  // continuous reader calls it after switching scenes under a selection
321|  // that started elsewhere, so the popover follows without a second tap.
322|  const rescan = useCallback(() => {
323|    const view = viewNodeRef.current;
324|    if (!view) return;
325|    const sel = window.getSelection();
326|    const text = sel?.toString().trim() ?? "";
327|    if (!sel || sel.isCollapsed || text.length < 3 || !sel.rangeCount) {
328|      setPopover(null);
329|      return;
330|    }
331|    if (!view.contains(sel.anchorNode) || !view.contains(sel.focusNode)) {
332|      setPopover(null);
333|      return;
334|    }
335|    const range = sel.getRangeAt(0);
336|    rangeRef.current = range.cloneRange();
337|    setPopover(popoverPos(range.getBoundingClientRect(), { x: window.scrollX, y: window.scrollY }));
338|  }, []);
339|
340|  useEffect(() => {
