26|export const MSG_CREDITS_OUT =
27|  "So many people loved this that we've run out of credits to share. " +
28|  "Feel free to bring your own key! Meanwhile, The Wonderful Wizard of Oz " +
29|  "is ready to read, with its soundtrack and illustrations.";
