59|function isRecord(json: unknown): json is Record<string, unknown> {
60|  return typeof json === "object" && json !== null && !Array.isArray(json);
61|}
62|
63|// Strict parse at the trust boundary: exact fields only, so a client
64|// bug cannot silently spend budget on a misread request.
65|export function parseImageRequest(json: unknown): ImageRequest {
66|  if (!isRecord(json)) throw new ImageValidationError();
67|  const { kind } = json;
68|  if (kind === "passage") {
69|    const keys = Object.keys(json).sort().join(",");
70|    if (keys !== "bookId,kind,n,textVersion" && keys !== "bookId,kind,n,style,textVersion") {
71|      throw new ImageValidationError();
72|    }
73|    if (typeof json.bookId !== "string" || json.bookId.length === 0) throw new ImageValidationError();
74|    if (typeof json.textVersion !== "string" || json.textVersion.length === 0) {
75|      throw new ImageValidationError();
76|    }
77|    if (typeof json.n !== "number" || !Number.isInteger(json.n)) throw new ImageValidationError();
78|    const style = parseStyleChoice(json.style);
79|    return {
80|      kind: "passage",
81|      bookId: json.bookId,
82|      textVersion: json.textVersion,
83|      n: json.n,
84|      ...(style === undefined ? {} : { style }),
85|    };
86|  }
87|  if (kind === "scene") {
88|    const keys = Object.keys(json).sort().join(",");
89|    if (keys !== "bookId,kind,sceneId,textVersion" && keys !== "bookId,kind,sceneId,style,textVersion") {
90|      throw new ImageValidationError();
91|    }
92|    if (typeof json.bookId !== "string" || json.bookId.length === 0) throw new ImageValidationError();
93|    if (typeof json.textVersion !== "string" || json.textVersion.length === 0) {
94|      throw new ImageValidationError();
95|    }
96|    if (typeof json.sceneId !== "string" || json.sceneId.length === 0) throw new ImageValidationError();
97|    const style = parseStyleChoice(json.style);
98|    return {
99|      kind: "scene",
100|      bookId: json.bookId,
101|      textVersion: json.textVersion,
102|      sceneId: json.sceneId,
103|      ...(style === undefined ? {} : { style }),
104|    };
105|  }
106|  throw new ImageValidationError();
107|}
108|
109|export interface BookRef {
110|  id: string;
111|  textVersion: string;
112|  paragraphNs: Set<number>;
113|  sceneIds: Set<string>;
114|}
115|
116|// Checks the parsed request against the frozen book text.
117|export function validateAgainstBook(req: ImageRequest, book: BookRef): void {
118|  if (req.bookId !== book.id) throw new ImageValidationError();
119|  if (req.textVersion !== book.textVersion) throw new ImageValidationError();
120|  if (req.kind === "passage") {
121|    if (!book.paragraphNs.has(req.n)) throw new ImageValidationError();
122|    return;
123|  }
124|  if (!book.sceneIds.has(req.sceneId)) throw new ImageValidationError();
125|}
126|
127|// One paragraph maps to one image; one scene maps to one image. A styled
128|// image keeps the same base with a style segment before the file name, so
129|// an omitted style keys byte-identically to today.
130|export function imageKey(req: ImageRequest): string {
131|  const base = `images/${req.bookId}/${req.textVersion}/${PROMPT_VERSION}`;
132|  const file = req.kind === "passage" ? `p${req.n}.webp` : `scene-${req.sceneId}.webp`;
133|  return req.style === undefined ? `${base}/${file}` : `${base}/${styleSegment(req.style)}/${file}`;
134|}
135|
136|export function indexKeyFor(key: string): string {
137|  return `img:index:${key}`;
138|}
139|
140|export function lockKeyFor(key: string): string {
141|  return `img:lock:${key}`;
142|}
143|
144|export function quotaKeys(args: { day: string; ipHash: string; anonId: string }): {
145|  ip: string;
146|  anon: string;
147|} {
148|  return {
149|    ip: `img:quota:ip:${args.day}:${args.ipHash}`,
150|    anon: `img:quota:anon:${args.day}:${args.anonId}`,
151|  };
152|}
153|
154|export function spendKey(): string {
155|  return "img:spend:micro";
156|}
157|
158|// Daily spend counter for our key. The day is the UTC day string
159|// YYYY-MM-DD the caller already uses for quota keys, so the daily
160|// cap resets on UTC rollover together with per-person quota.
161|export const DAILY_SPEND_TTL_SEC = 48 * 3600;
162|
163|export function dailySpendKey(day: string): string {
164|  return `img:spend:daily:${day}`;
165|}
166|
167|export function overQuota(count: number): boolean {
168|  return count > DAILY_IMAGE_LIMIT;
169|}
170|
171|export function budgetExceeded(totalAfterReserve: number, capMicro: number): boolean {
172|  return totalAfterReserve > capMicro;
173|}
174|
175|export function imageCostMicro(): number {
176|  return IMAGE_COST_MICRO;
177|}
