179|// Lets the route compare lock tokens without touching Redis twice.
180|export function canRelease(expected: string, actual: string | null): boolean {
181|  return actual !== null && actual === expected;
182|}
183|
184|function clip(text: string, max: number): string {
185|  const clean = text.replace(/\s+/g, " ").trim();
186|  if (clean.length <= max) return clean;
187|  return clean.slice(0, max).trimEnd();
188|}
