116|// Checks the parsed request against the frozen book text.
117|export function validateAgainstBook(req: ImageRequest, book: BookRef): void {
118|  if (req.bookId !== book.id) throw new ImageValidationError();
119|  if (req.textVersion !== book.textVersion) throw new ImageValidationError();
120|  if (req.kind === "passage") {
121|    if (!book.paragraphNs.has(req.n)) throw new ImageValidationError();
