229|// In-memory KV for tests. Expiries are checked against Date.now.
230|export function createMemoryKV(): KV & { clear(): void } {
231|  const values = new Map<string, string>();
232|  const expiresAt = new Map<string, number>();
233|  function live(key: string): boolean {
234|    const until = expiresAt.get(key);
235|    if (until !== undefined && Date.now() >= until) {
236|      values.delete(key);
237|      expiresAt.delete(key);
238|      return false;
239|    }
240|    return true;
241|  }
242|  function num(key: string): number {
243|    return Number(values.get(key) ?? "0");
244|  }
245|  return {
246|    async get(key: string): Promise<string | null> {
247|      if (!live(key)) return null;
248|      return values.get(key) ?? null;
249|    },
250|    async setNxEx(key: string, value: string, exSec: number): Promise<boolean> {
251|      if (live(key) && values.has(key)) return false;
252|      values.set(key, value);
253|      expiresAt.set(key, Date.now() + exSec * 1000);
254|      return true;
255|    },
256|    async set(key: string, value: string): Promise<void> {
257|      values.set(key, value);
258|      expiresAt.delete(key);
259|    },
260|    async incr(key: string): Promise<number> {
261|      const next = num(key) + 1;
262|      values.set(key, String(next));
263|      return next;
264|    },
265|    async incrBy(key: string, by: number): Promise<number> {
266|      const next = num(key) + by;
267|      values.set(key, String(next));
268|      return next;
269|    },
270|    async decr(key: string): Promise<number> {
271|      const next = num(key) - 1;
272|      values.set(key, String(next));
273|      return next;
274|    },
275|    async decrBy(key: string, by: number): Promise<number> {
276|      const next = num(key) - by;
277|      values.set(key, String(next));
278|      return next;
279|    },
280|    async expire(key: string, sec: number): Promise<void> {
281|      if (values.has(key)) expiresAt.set(key, Date.now() + sec * 1000);
282|    },
283|    async releaseIfToken(key: string, token: string): Promise<boolean> {
284|      if (!live(key)) return false;
285|      if (values.get(key) !== token) return false;
286|      values.delete(key);
287|      expiresAt.delete(key);
288|      return true;
289|    },
290|    clear(): void {
291|      values.clear();
292|      expiresAt.clear();
293|    },
294|  };
