43|// One pass, no skipped steps: hit -> lock -> human -> quota -> budget ->
44|// generate -> store -> index -> release. Every failure after the reserve
45|// refunds quota, budget, and the daily counter and releases the lock.
46|export async function orchestrate(
47|  req: ImageRequest,
48|  deps: OrchestrateDeps,
49|): Promise<ImageResponse> {
50|  const key = imageKey(req);
51|  const indexKey = indexKeyFor(key);
52|  const lockKey = lockKeyFor(key);
53|  // deps.day is the UTC day string (YYYY-MM-DD), shared with quota keys.
54|  const dailyKey = dailySpendKey(deps.day);
55|
56|  const indexed = await deps.kv.get(indexKey);
57|  if (indexed) {
58|    return { status: "ready", url: indexed, cached: true, caption: captionFor(req, deps.content) };
59|  }
60|  const existing = await deps.store.findUrl(key);
61|  if (existing) {
62|    await deps.kv.set(indexKey, existing);
63|    return { status: "ready", url: existing, cached: true, caption: captionFor(req, deps.content) };
64|  }
65|
66|  const token = deps.token ?? randomUUID();
67|  if (!(await deps.kv.setNxEx(lockKey, token, LOCK_TTL_SEC))) return { status: "pending" };
68|
69|  // Best-effort unlock: a release failure must never turn into a client 500.
70|  const release = async (): Promise<void> => {
71|    try {
72|      await deps.kv.releaseIfToken(lockKey, token);
73|    } catch {
74|      // Lock expires on its own; nothing to do.
75|    }
76|  };
77|
78|  const keys = quotaKeysFor({ day: deps.day, ip: deps.ip, salt: deps.env.ipSalt, anonId: deps.anonId });
79|  let quotaTaken = false;
80|  let spendTaken = false;
81|  let dailySpendTaken = false;
82|  // Best-effort refunds that clear their flag only after the write lands,
83|  // so the outer catch refunds each reserve exactly once.
84|  const refundQuotaOnce = async (): Promise<void> => {
85|    try {
86|      await refundQuota(deps.kv, keys);
87|      quotaTaken = false;
88|    } catch {
89|      // Redis down: nothing reserved server-side to retry against.
90|    }
91|  };
92|  const refundSpendOnce = async (): Promise<void> => {
93|    try {
94|      await deps.kv.decrBy(spendKey(), imageCostMicro());
95|      spendTaken = false;
96|    } catch {
97|      // Redis down: nothing reserved server-side to retry against.
98|    }
99|  };
100|  const refundDailySpendOnce = async (): Promise<void> => {
101|    try {
102|      await deps.kv.decrBy(dailyKey, imageCostMicro());
103|      dailySpendTaken = false;
104|    } catch {
105|      // Redis down: nothing reserved server-side to retry against.
106|    }
107|  };
108|
109|  try {
110|    if (!verifyHuman()) {
111|      await release();
112|      return { status: "error", code: "unavailable", message: MSG_FAILED };
113|    }
114|
115|    if (!(await checkQuota(deps.kv, keys)).ok) {
116|      await release();
117|      return { status: "error", code: "quota", message: MSG_QUOTA };
118|    }
119|    quotaTaken = true;
120|
121|    // Both caps apply only to requests paid with our key. The future
122|    // BYOK path must skip these reserves and check its own key instead.
123|    const total = await deps.kv.incrBy(spendKey(), imageCostMicro());
124|    spendTaken = true;
125|    if (budgetExceeded(total, deps.env.spendCapMicro)) {
126|      await refundSpendOnce();
127|      await refundQuotaOnce();
128|      await release();
129|      return { status: "error", code: "budget", message: MSG_CREDITS_OUT };
130|    }
131|
132|    const dailyTotal = await deps.kv.incrBy(dailyKey, imageCostMicro());
133|    dailySpendTaken = true;
134|    // Refresh the expiry on every reserve: cheap, idempotent, and keeps
135|    // the key alive through a busy day without a separate read.
136|    await deps.kv.expire(dailyKey, DAILY_SPEND_TTL_SEC);
137|    if (budgetExceeded(dailyTotal, deps.env.dailySpendCapMicro)) {
138|      await refundDailySpendOnce();
139|      await refundSpendOnce();
140|      await refundQuotaOnce();
141|      await release();
142|      return { status: "error", code: "daily_budget", message: MSG_CREDITS_OUT };
143|    }
144|
145|    let bytes: Uint8Array;
146|    try {
147|      bytes = await deps.generate.generate(
148|        buildPrompt({
149|          kind: req.kind,
150|          passageText: deps.content.passageText,
151|          sceneTitle: deps.content.sceneTitle,
152|          sceneClip: deps.content.sceneClip,
153|          style: req.style,
154|        }),
155|      );
156|    } catch (e) {
157|      await refundDailySpendOnce();
158|      await refundSpendOnce();
159|      await refundQuotaOnce();
160|      await release();
161|      console.error(`image generate failed: ${errorTag(e)}`);
162|      return { status: "error", code: "unavailable", message: MSG_FAILED };
