216|    inFlight = mine;
217|    setPopover(null);
218|    setHintAt(null);
219|    setCard({ phase: "loading" });
220|    void poll({ kind: "scene", bookId, textVersion, sceneId, ...requestStyleFields(prefRef.current) })
