312|  const removeFigure = useCallback(
313|    (id: string) => {
314|      storeFigures(sceneId, (prev) => prev.filter((f) => f.id !== id));
315|    },
316|    [storeFigures, sceneId],
317|  );
318|
319|  // Re-read the live selection against the current text view. The
320|  // continuous reader calls it after switching scenes under a selection
321|  // that started elsewhere, so the popover follows without a second tap.
322|  const rescan = useCallback(() => {
323|    const view = viewNodeRef.current;
324|    if (!view) return;
325|    const sel = window.getSelection();
326|    const text = sel?.toString().trim() ?? "";
327|    if (!sel || sel.isCollapsed || text.length < 3 || !sel.rangeCount) {
328|      setPopover(null);
329|      return;
330|    }
331|    if (!view.contains(sel.anchorNode) || !view.contains(sel.focusNode)) {
332|      setPopover(null);
333|      return;
334|    }
335|    const range = sel.getRangeAt(0);
336|    rangeRef.current = range.cloneRange();
337|    setPopover(popoverPos(range.getBoundingClientRect(), { x: window.scrollX, y: window.scrollY }));
338|  }, []);
339|
340|  useEffect(() => {
341|    const view = viewEl;
342|    if (!view) return;
343|    let frame = 0;
344|    const onMouseUp = () => {
345|      cancelAnimationFrame(frame);
346|      frame = requestAnimationFrame(rescan);
347|    };
348|    view.addEventListener("mouseup", onMouseUp);
349|    return () => {
350|      cancelAnimationFrame(frame);
351|      view.removeEventListener("mouseup", onMouseUp);
352|    };
353|  }, [viewEl, rescan]);
354|
355|  useEffect(() => {
356|    if (!popover) return;
357|    const hide = () => setPopover(null);
358|    let frame = 0;
359|    // Capture phase sees scrolls from inner containers too (they do not
360|    // bubble), so the pill tracks the text in any reader layout.
361|    const onScroll = () => {
362|      cancelAnimationFrame(frame);
363|      frame = requestAnimationFrame(() => {
364|        const box = rangeRef.current?.getBoundingClientRect();
365|        if (!box || (box.width === 0 && box.height === 0)) {
366|          hide();
367|          return;
368|        }
369|        const next = popoverPos(box, { x: window.scrollX, y: window.scrollY });
370|        setPopover((prev) => (prev && prev.top === next.top && prev.left === next.left ? prev : next));
371|      });
372|    };
373|    const onDown = (event: MouseEvent) => {
374|      if (!popRef.current?.contains(event.target as Node | null)) hide();
375|    };
376|    const onKey = (event: KeyboardEvent) => {
377|      if (event.key === "Escape") hide();
378|    };
