380|    document.addEventListener("keydown", onKey);
381|    window.addEventListener("resize", hide);
382|    document.addEventListener("scroll", onScroll, { capture: true, passive: true });
383|    return () => {
384|      cancelAnimationFrame(frame);
385|      document.removeEventListener("scroll", onScroll, { capture: true });
386|      document.removeEventListener("mousedown", onDown);
387|      document.removeEventListener("keydown", onKey);
388|      window.removeEventListener("resize", hide);
389|    };
390|  }, [popover]);
