401|    () => (popover && hintAt?.where === "popover" ? { ...popover, hint } : popover),
402|    [popover, hintAt, hint],
403|  );
404|  const shownFigures = useMemo(() => {
405|    if (hintAt?.where !== "figure") return figures;
406|    const id = hintAt.id;
407|    return figures.map((f) => (f.id === id && f.phase === "error" ? { ...f, message: hint } : f));
408|  }, [figures, hintAt, hint]);
409|
410|  return {
411|    card: shownCard,
412|    figures: shownFigures,
413|    popover: shownPopover,
414|    viewRef,
415|    popRef,
416|    illustrateScene,
417|    illustratePassage,
418|    hidePopover,
419|    rescan,
420|    clearScene,
421|    removeFigure,
422|    retryFigure,
423|    lightbox: { item: lightbox, open: openLightbox, close: closeLightbox },
424|  };
